const { p, h1, h2, h3, bullets, numbered, table, note, fig, spacer } = require("./lib");
const d = require("./data");
const cm = d.ai.confusion_matrix;
const recall = (i) => ((cm[i][i] / cm[i].reduce((a, b) => a + b, 0)) * 100).toFixed(1);

exports.q5 = () => [
  h1("Question 5: Evaluation and Responsible Use"),
  h2("5.1 Test summary"),
  p(`All automated tests were run together with coverage (\`pytest tests --cov=app\`). Result: **${d.ev.tests.length} passed, 0 failed**, line coverage **${d.f1(d.ev.coverage)}%** of \`app/\` measured in-process (the separately launched server used in ST-01 and ST-02 is not included in the coverage figure).`),
  table(["Level", "Tests", "Passed", "Tooling", "What it covers"], [
    ["Unit", String(d.count("UT")), String(d.passed("UT")), "pytest", "Tokens, hashing, distance and georeferencing maths, validation, CNN accuracy, hotspot accuracy, spread model, HAL adapters, frame codec."],
    ["Integration", String(d.count("IT")), String(d.passed("IT")), "pytest, FastAPI TestClient, WebSocket", "API + database + WebSocket + AI together: login, dispatch, security errors, queueing, real-time events, privacy filtering, reports, full simulated mission."],
    ["System", String(d.count("ST")), String(d.passed("ST")), "pytest with a real `uvicorn` process", "ST-01: live mission with latency, rate and CPU measurement. ST-02: TLS 1.3 negotiation."],
    ["Browser (system)", "1 script", "Run", "Playwright + Chromium", "Cold-load time on a throttled 10 Mbps link; sign-in, dispatch, message, close and report for operator, commander and crew; screenshots."],
    ["User acceptance", "0", "n/a", "n/a", "**Not executed.** See the plan below."],
  ], [14, 9, 9, 24, 44], { size: 16 }),
  h3("Representative test results"),
  table(["Test case", "Expected", "Actual", "Status", "Evidence"], [
    ["UT-01 Token tamper and expiry", "Altered or expired token rejected", "Both rejected; valid token accepted", ["Pass"], "junit.xml"],
    ["UT-06 CNN on 450 fresh frames", "At least 90% correct", "445 of 450 correct (98.9%)", ["Pass"], "junit.xml; `ai_metrics.json`"],
    ["UT-07 Hotspot position error", "95th percentile under 5 m", `Test passed (p95 under 5 m). Wider sweep of ${d.geo.n} detections: p95 ${d.geo.p95} m, ${d.geo.within} within 5 m, worst ${d.geo.max} m`, ["Pass"], "junit.xml; `evidence.json`"],
    ["UT-08 Spread direction", "Extends downwind; larger with stronger wind", "East extent greater than west for a west wind; forward reach grows with wind", ["Pass"], "junit.xml"],
    ["IT-02 Nearest-drone dispatch", "Soshanguve call → DR-03 within 30 s; next call → DR-01", "DR-03, then DR-01; dispatch time under 1 s", ["Pass"], "junit.xml"],
    ["IT-03 Security and validation", "401 no token, 403 crew CAD, 422 bad priority, 409 duplicate", "All four returned as expected", ["Pass"], "junit.xml; Section 4.3"],
    ["IT-04 No drone available", "Incident queued, not dispatched", "`dispatchStatus = queued`", ["Pass"], "junit.xml"],
    ["IT-05 Telemetry to dashboard", "Received within 500 ms", "Received; assertion under 500 ms held", ["Pass"], "junit.xml"],
    ["IT-06 AI analysis and events", "Critical frame stored; events detection, hotspots, alert in order; bad frame 422", "As expected; inference under 100 ms", ["Pass"], "junit.xml"],
    ["IT-07 Crew privacy", "Commander gets location and telemetry; crew get only incident and message events", "As expected", ["Pass"], "junit.xml"],
    ["IT-09 Close and report", "Operator 403; commander closes; report has 4 frames, max severity 2; second close 409", "As expected", ["Pass"], "junit.xml"],
    ["IT-11 Simulated mission", "Drone reaches scene, 5+ detections, closes to idle, report exists", "Passed (24.7 s test)", ["Pass"], "junit.xml"],
    ["ST-01 Live mission", "Telemetry p95 under 500 ms; inference p95 under 100 ms; critical alert; report", `Telemetry p95 ${d.sys.telemetry_latency_ms.p95} ms; inference p95 ${d.sys.inference_ms.p95} ms; alert raised; ${d.sys.report_frames_analysed} frames in report`, ["Pass"], "`system_metrics.json`"],
    ["ST-02 TLS 1.3", "TLS 1.3 negotiated", `Negotiated ${d.sys.tls_negotiated}; TLS 1.2-only client refused: ${d.sys.tls12_only_client_refused}`, ["Pass"], "`system_metrics.json`"],
    ["UI-01 Dashboard load (5 cold loads)", "Under 3 s at 10 Mbps", `Median ${d.ui.dashboard_load_s_10mbps.median} s, max ${d.ui.dashboard_load_s_10mbps.max} s`, ["Pass"], "`ui_metrics.json`"],
  ], [21, 24, 30, 8, 17], { statusCol: 3, size: 15 }),
  h3("User acceptance testing (planned, not executed)"),
  p("No City of Tshwane fire personnel or other end users took part, so **no acceptance result is claimed**. The scenarios from Assignment 2 remain the plan:"),
  table(["UAT", "Scenario", "Participants", "Pass criterion", "Status"], [
    ["UAT-01", "Informal-settlement fire response", "2+ incident commanders", "Commander can find the incident, read AI class and hotspots, and message crews without help", ["Not executed"]],
    ["UAT-02", "Wildfire spread prediction", "Commander, operator", "Spread polygon judged useful", ["Not executed"]],
    ["UAT-03", "Multi-crew tracking", "Commander, crew", "All crew positions visible; positions update", ["Not executed"]],
    ["UAT-04", "Post-incident report review", "Commander", "Average rating 4/5 or higher; 80% call it an improvement (Assignment 1 criterion)", ["Not executed"]],
  ], [9, 24, 18, 37, 12], { statusCol: 4, size: 16 }),
  spacer(60),
  p("What was done instead is a developer walkthrough: scripted browser sessions for the operator, commander and crew roles ran the complete workflow (`scripts/ui_capture.py`) and produced the screenshots in Section 4.1. That checks the interface works. It does not test whether real users find it usable."),

  h2("5.2 Quantitative evaluation"),
  h3("Non-functional requirements"),
  table(["Requirement", "Target", "Measured", "Method and caveat", "Verdict"], [
    ["NFR-02 Dashboard load", "3 s or less at 10 Mbps", `Median ${d.ui.dashboard_load_s_10mbps.median} s; max ${d.ui.dashboard_load_s_10mbps.max} s`, "Chromium with 10 Mbps, 40 ms latency, cache off, 5 runs; map tiles blocked because they come from a third party; server on the same machine.", ["Pass"]],
    ["NFR-10 Encryption in transit", "TLS 1.3", `${d.sys.tls_negotiated} negotiated; TLS 1.2-only client refused`, "Self-signed certificate on the running server. Production would terminate TLS at the gateway.", ["Pass"]],
    ["NFR-10 Encryption at rest", "AES-256 in Atlas", "Not measured", "Atlas setting; the prototype used an in-memory store.", ["Not met"]],
    ["FR-02 Telemetry latency", "500 ms or less", `p50 ${d.sys.telemetry_latency_ms.p50} ms, p95 ${d.sys.telemetry_latency_ms.p95} ms, max ${d.sys.telemetry_latency_ms.max} ms`, `${d.sys.telemetry_events} events at ${d.sys.telemetry_rate_hz} Hz; server timestamp to client receive on localhost. Real networks add delay.`, ["Pass"]],
    ["NFR-01 Uptime 99.5%", "99.5% with failover", "Not measured", "Longest continuous run was under a minute; there is one process and no failover.", ["Not met"]],
  ], [17, 14, 22, 37, 10], { statusCol: 4, size: 15 }),
  h3("Emerging-technology metrics"),
  table(["Metric", "Target", "Measured", "Verdict"], [
    ["Inference time (ETR-02, FR-03)", "100 ms or less per frame", `median ${d.sys.inference_ms.p50} ms, p95 ${d.sys.inference_ms.p95} ms, max ${d.sys.inference_ms.max} ms (${d.sys.detections} frames, CPU only)`, ["Pass"]],
    ["Sustained frame rate (ETR-02)", "10 frames/s or more", `${d.sys.frame_rate_fps} frames/s over the 15 s on-scene window`, ["Pass"]],
    ["CPU use (ETR-02)", "80% or less", `${d.f1(d.sys.server_cpu_percent_of_one_core)}% of one core on a ${d.sys.cpu_cores_available}-core VM (not an Azure App Service instance)`, ["Partial"]],
    ["CNN accuracy (ETR-01)", "90% or more on FLAME", `${(d.ai.val_accuracy * 100).toFixed(2)}% on synthetic validation data; FLAME not evaluated`, ["Partial"]],
    ["Hotspot position error (ETR-04)", "5 m or less", `median ${d.geo.p50} m, p95 ${d.geo.p95} m, ${d.geo.pct}% within 5 m, worst ${d.geo.max} m (simulated ground truth)`, ["Partial"]],
  ], [26, 20, 44, 10], { statusCol: 3, size: 15 }),
  spacer(60),
  p(`**Confusion matrix** (synthetic validation set, ${d.ai.val_samples} frames; rows are the true class):`, { keepNext: true }),
  table(["True \\ Predicted", "No Fire", "Fire", "Critical", "Recall"], [
    ["No Fire", String(cm[0][0]), String(cm[0][1]), String(cm[0][2]), recall(0) + "%"],
    ["Fire", String(cm[1][0]), String(cm[1][1]), String(cm[1][2]), recall(1) + "%"],
    ["Critical", String(cm[2][0]), String(cm[2][1]), String(cm[2][2]), recall(2) + "%"],
  ], [28, 18, 18, 18, 18], { firstFill: true, boldFirst: true }),
  spacer(60),
  p(`The most important error for safety is that ${cm[2][1]} of 400 Critical frames (${(100 - parseFloat(recall(2))).toFixed(1)}%) were labelled Fire, which understates severity. The hotspots and the commander's own judgement remain visible, but the alert banner would not fire on those frames.`),

  h2("5.3 User guide for the main workflow"),
  p("Main workflow: from a fire call to a closed incident with a report. Figure numbers refer to the screenshots in Section 4.1 (Figures 8 to 14)."),
  ...numbered([
    "**Sign in** (Figure 8). Open the dashboard address, enter your username and password. The header shows your name and role, and \"live\" at the top right means the real-time connection is working.",
    "**Raise or receive the call** (Figure 9). In production the CAD system posts the alert. For a demonstration, an operator or admin clicks **Simulate CAD alert**. An incident such as INC-0001 appears in the list.",
    "**Watch the dispatch** (Figure 10). The nearest idle drone is assigned and the incident shows `en_route`. The **Drone telemetry** panel shows position, altitude, battery and heading updating about ten times per second.",
    "**Read the AI analysis** (Figure 11). When the drone is on scene the **AI thermal analysis** panel shows the latest thermal frame, the class (No Fire, Fire or Critical), the confidence and the number of hotspots. Red circles on the map mark hotspots. The orange shape is the 15-minute fire-spread forecast; the **Fire spread** panel gives wind and forward reach. A red banner appears when severity first becomes Critical.",
    "**Direct the crews** (Figure 12). Select the incident, type in **Command channel** and press **Send**. Every signed-in user sees the message.",
    "**Close the incident** (Figure 13). A commander or admin selects the incident and presses **Close incident**. The drone is released and a report appears at the bottom of the side panel: dispatch time, duration, frames analysed, maximum severity, peak hotspots and message count.",
    "**Crew view** (Figure 14). Field crew see incidents and the command channel only. Telemetry and AI panels stay empty by design.",
  ], "steps2"),
  h3("Troubleshooting"),
  table(["Symptom", "Likely cause", "What to do"], [
    ["\"invalid credentials\" at sign-in", "Wrong username or password", "Re-enter. Ask an administrator for the correct account."],
    ["Status shows \"reconnecting…\"", "Server restarted or network lost", "Wait: the page reconnects every 2 s. If it persists, reload and sign in again."],
    ["Simulate button greyed out", "Your role is not operator or admin", "Sign in with an operator account."],
    ["Close incident greyed out", "No incident selected, incident already closed, or role is not commander/admin", "Select an open incident; use a commander account."],
    ["Incident stays \"queued\"", "No idle drone with battery of 30% or more", "Wait for a drone to finish, or recharge or register another."],
    ["No thermal image yet", "Drone still climbing above 20 m, or you are signed in as crew", "Wait a few seconds. Crew do not receive imagery."],
    ["Map has no streets", "Map tiles blocked or no internet", "Check the connection. Markers and overlays still work."],
    ["Everything stops after some hours", "Token expired (8 hours)", "Sign in again."],
    ["API returns 422", "A field is out of range or malformed", "Compare with the rules in Section 4.2."],
  ], [26, 34, 40], { size: 16 }),

  h2("5.4 Limitations, risks, ethics, maintenance and future work"),
  h3("Current limitations and unresolved risks"),
  table(["Area", "Limitation or risk", "Effect"], [
    ["Evidence", "All results come from simulation on one machine. No real drone, thermal camera, network or CAD feed was used.", "Real-world latency, accuracy and reliability are unknown."],
    ["AI data", "The CNN was trained on synthetic frames, not FLAME or local footage.", "Accuracy on real fires may be much lower; false negatives are the main safety risk."],
    ["AI errors", "3% of Critical test frames were labelled Fire.", "Severity can be understated."],
    ["Spread model", "Heuristic wind ellipse; terrain and fuel ignored; simulated wind unless a key is set.", "Forecast is indicative only."],
    ["Mobile app", "Not built (FR-08 Not met, FR-06 Partial). A crew account can post a location for any firefighter id.", "No glove-friendly field client; location spoofing possible."],
    ["Resilience", "Single process, in-memory store by default, no failover (NFR-01 Not met).", "Data lost on restart; no availability guarantee."],
    ["Security", "Seeded demo passwords, default JWT secret, no rate limiting or lockout, no token revocation, token in WebSocket URL.", "Must be fixed before any real deployment."],
    ["Scalability", "Synchronous database calls inside async handlers; telemetry stored at 10 Hz per drone without expiry.", "Event loop can block under load; collection grows quickly."],
    ["Testing", "No UAT with real users; Docker image and Azure deployment untested.", "Usability and deployability unproven."],
  ], [14, 50, 36], { size: 16 }),
  h3("Ethical, legal and security concerns"),
  bullets([
    "**Human in the loop.** The AI is advisory. Commanders decide; the interface shows confidence and the raw thermal frame so the classification can be questioned.",
    "**Privacy and surveillance.** Drones may film residents, and firefighter positions are personal data. Under POPIA the use needs a defined purpose, minimal collection, limited retention and access logging. Drone flights also need SACAA authorisation, which this project excludes from scope.",
    "**Bias and fairness.** Training data that under-represents informal-settlement materials could make detection worse where fires are most dangerous. Local footage should be added before use.",
    "**Accountability.** Reports record what the system detected and when, so decisions can be reviewed afterwards.",
    "**Worker monitoring.** Live crew tracking should be limited to active incidents and be explained to firefighters and their representatives.",
  ]),
  h3("Maintenance needs"),
  bullets([
    "Retrain and re-validate the model periodically, and before each production update; track false positives and negatives flagged by commanders.",
    "Keep dependencies (FastAPI, PyTorch, OpenCV, pymongo) patched, rotate the JWT secret and change seeded passwords.",
    "Run the test suite (`pytest`) in continuous integration on every change, as planned in Assignment 2 (GitHub Actions; not yet set up).",
    "Monitor latency, frame rate, disk growth in `telemetry`, and Atlas backups; test a restore at least once per quarter.",
  ]),
  h3("Two realistic future improvements"),
  numbered([
    "**Train and validate on real data.** Retrain on the FLAME dataset plus locally captured Tshwane footage, add a commander feedback loop for wrong classifications, re-check the 90% threshold and the 5 m localisation target on real flights, and implement the DJI adapter behind the existing HAL.",
    "**Make it field-ready.** Build the React Native crew app (glove-friendly, 44 px targets) bound to individual firefighter identities, move to Atlas with persistence and backups, run two or more replicas behind a gateway with health checks to earn the 99.5% target, and run UAT with City of Tshwane fire personnel.",
  ], "fut"),
  h2("References"),
  ...numbered([
    "ISJ107V Assignment 3 brief, S2 2026.",
    "FireSight Assignment 1 (project proposal, marked test 218503322) and Assignment 2 (technical specification).",
    "Shamsoshoara, A., Afghah, F., Razi, A., Zheng, L., Fulé, P.Z. and Blasch, E. (2021). Aerial imagery pile burn detection using deep learning: the FLAME dataset. *Computer Networks*, 193, 108001.",
    "Republic of South Africa. Protection of Personal Information Act 4 of 2013.",
    "FastAPI, PyTorch, OpenCV, MongoDB, Leaflet and Mermaid documentation for the versions in Section 3.6.",
  ], "refs"),
];
